{ "appendquerystring": false, "associatecurrentportaluser": false, "attachfile": false, "attachfileallowmultiple": false, "attachfilerequired": false, "attachfilerestrictaccept": false, "autogeneratesteps": false, "captcharequired": false, "entityname": "new_appdocs", "entitypermissionsenabled": false, "forceallfieldsrequired": false, "formname": "Portal", "geolocation_displaymap": false, "geolocation_enabled": false, "geolocation_maptype": 756150000, "hideformonsuccess": true, "mode": 100000000, "onsuccess": 756150000, "populatereferenceentitylookupfield": false, "portaluserlookupattributeisactivityparty": false, "recommendedfieldsrequired": true, "recordsourceallowcreateonnull": false, "redirecturlappendentityidquerystring": false, "referenceentityshowreadonlyform": false, "referencequerystringisprimarykey": true, "registerstartupscript": "
$(document).ready(function () {
 var expirydateField = document.getElementById('new_expirydate');
 if (expirydateField) {
 var parentTR = expirydateField.closest('tr');
 if (parentTR) {
 parentTR.style.display = 'none';
 }
 }
 const rightToWorkSelect = document.getElementById("new_righttoworktypeid");

 const allOptions = Array.from(rightToWorkSelect.options);

 function filterRightToWorkOptions(value) {
 rightToWorkSelect.innerHTML = '';

 if (value === "1") { // Yes
 const allowedValues = [
 "6b8623fb-6e13-ef11-9899-002248cbe992", // Birth Certificate
 "c156c2e1-6e13-ef11-9899-002248cbe992" // Passport
 ];
 const filtered = allOptions.filter(opt =>
 opt.value === "" || allowedValues.includes(opt.value)
 );
 filtered.forEach(opt => rightToWorkSelect.appendChild(opt));

 } else {
 const allowedValues = [
 "be578811-6f13-ef11-9899-002248cbe992", // Residence Permit
 "c156c2e1-6e13-ef11-9899-002248cbe992" // Passport
 ];
 const filtered = allOptions.filter(opt =>
 opt.value === "" || allowedValues.includes(opt.value)
 );
 filtered.forEach(opt => rightToWorkSelect.appendChild(opt));

 // allOptions.forEach(opt => rightToWorkSelect.appendChild(opt));
 }
 }

 const isUKResident = window.parent.isUKResident;
 console.log("isUKResident is: ", isUKResident);

 filterRightToWorkOptions(isUKResident);
});

